#include <vector>
#include <algorithm>
using namespace std;

class Solution {
public:
    int maximumANDSum(vector<int>& nums, int numSlots) {
        vector<int> power3(numSlots + 1, 1);
        for (int i = 1; i <= numSlots; ++i) {
            power3[i] = power3[i - 1] * 3;
        }

        const int totalStates = power3[numSlots];
        const int n = nums.size();
        vector<int> dp(totalStates, -1);
        dp[0] = 0;

        int answer = 0;
        for (int state = 0; state < totalStates; ++state) {
            if (dp[state] == -1) continue;

            int placed = 0;
            for (int x = state; x > 0; x /= 3) {
                placed += x % 3;
            }

            if (placed == n) {
                answer = max(answer, dp[state]);
                continue;
            }

            int occupancy = state;
            for (int slot = 0; slot < numSlots; ++slot) {
                if (occupancy % 3 < 2) {
                    int nextState = state + power3[slot];
                    dp[nextState] = max(
                        dp[nextState],
                        dp[state] + (nums[placed] & (slot + 1))
                    );
                }
                occupancy /= 3;
            }
        }

        return answer;
    }
};

